 688	\begin{definition}[Principal divisor]
 689	  \label{def:principal_divisor}
 690	  \source{hartshorne-algebraic-geometry:page-0148}
 691	  \lean{AlgebraicGeometry.Scheme.WeilDivisor.principal}
 692	  \leanok
 693	  \uses{def:codim1_cycles, def:order_at_point,
 694	    lem:rationalMap_order_finite_support}
 695	
 696	  For a nonzero \(f\in K(X)\), its principal divisor is
 697	  \[
 698	    \operatorname{div}(f)
 699	      =\sum_{Y\in X^{(1)}}\operatorname{ord}_Y(f)\,Y.
 700	  \]
 701	  The sum is finite by \cref{lem:rationalMap_order_finite_support}.
 702	\end{definition}
 703	
 704	\begin{lemma}[Coefficient of a principal divisor]
 705	  \label{lem:principal_apply}
 706	  \lean{AlgebraicGeometry.Scheme.WeilDivisor.principal_apply}
 707	  \leanok
 708	  \uses{def:principal_divisor}
 709	  For \(Y\in X^{(1)}\),
 710	  \[
 711	    \operatorname{div}(f)(Y)=\operatorname{ord}_Y(f).
 712	  \]
 713	\end{lemma}
 714	\begin{proof}
 715	  \leanok
 716	  This is the coefficient formula in the defining finite sum.
 717	\end{proof}
 718	
 719	\begin{lemma}[Principal divisor of one]
 720	  \label{lem:principal_one}
 721	  \lean{AlgebraicGeometry.Scheme.WeilDivisor.principal_one}
 722	  \leanok
 723	  \uses{def:principal_divisor}
 724	  One has \(\operatorname{div}(1)=0\).
 725	\end{lemma}
 726	\begin{proof}
 727	  \leanok
 728	  \uses{lem:principal_apply, lem:order_one}
 729	  Every coefficient is \(\operatorname{ord}_Y(1)=0\).
 730	\end{proof}
