 732	\begin{theorem}[The principal-divisor homomorphism]
 733	  \label{thm:principal_hom}
 734	  \source{hartshorne-algebraic-geometry:page-0148}
 735	  \lean{AlgebraicGeometry.Scheme.WeilDivisor.principal_hom}
 736	  \leanok
 737	  \uses{def:principal_divisor}
 738	
 739	  The assignment
 740	  \[
 741	    K(X)^\times\longrightarrow\operatorname{Div}(X),
 742	    \qquad f\longmapsto\operatorname{div}(f)
 743	  \]
 744	  is a homomorphism from the multiplicative group to the additive group.
 745	\end{theorem}
 746	\begin{proof}
 747	  \leanok
 748	  \uses{lem:principal_apply, lem:order_mul_of_ne_zero, lem:order_one}
 749	  Compare coefficients at every \(Y\).  The product formula for the order
 750	  gives
 751	  \(\operatorname{div}(fg)(Y)=\operatorname{div}(f)(Y)
 752	    +\operatorname{div}(g)(Y)\), and \cref{lem:order_one} treats the
 753	  identity.
 754	\end{proof}
