 756	\section{Degree under finite morphisms}
 757	
 758	\begin{definition}[Pullback of a divisor along a finite morphism of curves]
 759	  \label{def:finite_curve_divisor_pullback}
 760	  \source{hartshorne-algebraic-geometry:page-0154}
 761	  \uses{lem:curve_closed_point_prime_divisor, def:order_at_point}
 762	
 763	  Let \(\varphi\colon C\to D\) be a finite morphism of nonsingular curves
 764	  over an algebraically closed field.
 765	  For a closed point \(Q\in D\), choose a local parameter \(t\) at \(Q\) and
 766	  set
 767	  \[
 768	    \varphi^*[Q]
 769	      =\sum_{\varphi(P)=Q}\operatorname{ord}_P(t)\,[P].
 770	  \]
 771	  This is independent of the local parameter and extends linearly to
 772	  \(\varphi^*\colon\operatorname{Div}(D)\to\operatorname{Div}(C)\).
 773	\end{definition}
 774	
 775	\begin{theorem}[Degree of a finite pullback]
 776	  \label{thm:finite_curve_degree_pullback}
 777	  \source{hartshorne-algebraic-geometry:page-0155}
 778	  \uses{def:finite_curve_divisor_pullback, def:divisor_degree}
 779	
 780	  If \(\varphi\colon C\to D\) is a finite morphism of complete nonsingular
 781	  curves over an algebraically closed field and
 782	  \(E\in\operatorname{Div}(D)\), then
 783	  \[
 784	    \deg(\varphi^*E)=\deg(\varphi)\deg(E).
 785	  \]
 786	\end{theorem}
 787	\begin{proof}
 788	  It suffices to take \(E=[Q]\).  On an affine neighbourhood
 789	  \(\operatorname{Spec}B\) of \(Q\), let \(A\) be the integral closure of
 790	  \(B\) in \(K(C)\), localize at \(Q\), and write the resulting finite
 791	  torsion-free \(\mathcal O_{D,Q}\)-module as a free module of rank
 792	  \([K(C):K(D)]=\deg(\varphi)\).  If \(t\) is a local parameter at \(Q\),
 793	  the dimension of \(A/tA\) is this rank.  Decomposing \(A/tA\) at the
 794	  points \(P\) over \(Q\) identifies the same dimension with
 795	  \(\sum_{\varphi(P)=Q}\operatorname{ord}_P(t)\), which is
 796	  \(\deg(\varphi^*[Q])\).
 797	\end{proof}
