 799	\begin{lemma}[A rational function gives a finite map to the projective line]
 800	  \label{lem:rational_function_finite_map_to_p1}
 801	  \source{hartshorne-algebraic-geometry:page-0155}
 802	  \uses{def:finite_curve_divisor_pullback, def:principal_divisor}
 803	
 804	  Let \(C\) be a complete nonsingular curve over an algebraically closed field
 805	  \(k\), and let
 806	  \(f\in K(C)\setminus k\).  There is a finite morphism
 807	  \(\varphi_f\colon C\to\mathbb P^1_k\) inducing the inclusion
 808	  \(k(f)\subseteq K(C)\), and
 809	  \[
 810	    \operatorname{div}(f)
 811	      =\varphi_f^*([0]-[\infty]).
 812	  \]
 813	\end{lemma}
 814	\begin{proof}
 815	  The rational function defines a morphism to \(\mathbb P^1\) because \(C\)
 816	  is complete and nonsingular.  It is nonconstant, hence dominant; the
 817	  induced extension \(K(C)/k(f)\) is finite, so the morphism is finite.
 818	  At every closed point, the pullback multiplicity of \(0\) or \(\infty\)
 819	  is respectively the order of the zero or the pole of \(f\).  Equality of
 820	  all coefficients gives the divisor formula.
 821	\end{proof}
