 823	\begin{theorem}[Principal divisors have degree zero]
 824	  \label{thm:principal_deg_zero}
 825	  \source{hartshorne-algebraic-geometry:page-0155}
 826	  \lean{AlgebraicGeometry.Scheme.WeilDivisor.principal_degree_zero}
 827	  \notready
 828	  \uses{def:principal_divisor, def:divisor_degree}
 829	
 830	  Let \(C\) be a complete nonsingular curve over an algebraically closed
 831	  field.  For every nonzero \(f\in K(C)\),
 832	  \[
 833	    \deg(\operatorname{div}(f))=0.
 834	  \]
 835	\end{theorem}
 836	\begin{proof}
 837	  \uses{lem:rational_function_finite_map_to_p1,
 838	    thm:finite_curve_degree_pullback}
 839	  If \(f\) is constant, its order at every point is zero.  Otherwise
 840	  \cref{lem:rational_function_finite_map_to_p1} gives a finite morphism
 841	  \(\varphi_f\colon C\to\mathbb P^1\) with
 842	  \(\operatorname{div}(f)=\varphi_f^*([0]-[\infty])\).  Therefore
 843	  \[
 844	    \deg(\operatorname{div}(f))
 845	      =\deg(\varphi_f)\deg([0]-[\infty])
 846	      =\deg(\varphi_f)(1-1)=0
 847	  \]
 848	  by \cref{thm:finite_curve_degree_pullback}.
 849	\end{proof}
