 943	\section{Linear equivalence and the divisor class group}
 944	
 945	\begin{definition}[Linear equivalence]
 946	  \label{def:linear_equivalence}
 947	  \source{hartshorne-algebraic-geometry:page-0148}
 948	  \lean{AlgebraicGeometry.Scheme.WeilDivisor.LinearEquivalence}
 949	  \leanok
 950	  \uses{def:principal_divisor}
 951	
 952	  Two divisors \(D,D'\in\operatorname{Div}(X)\) are linearly equivalent,
 953	  written \(D\sim D'\), if there is a nonzero \(f\in K(X)\) such that
 954	  \[
 955	    D-D'=\operatorname{div}(f).
 956	  \]
 957	\end{definition}
 958	
 959	\begin{lemma}[Linear equivalence is an equivalence relation]
 960	  \label{lem:linear_equivalence_equivalence}
 961	  \uses{def:linear_equivalence}
 962	  Linear equivalence is reflexive, symmetric, and transitive.
 963	\end{lemma}
 964	\begin{proof}
 965	  \uses{thm:principal_hom, lem:principal_one, lem:order_units_inv}
 966	  Reflexivity uses \(\operatorname{div}(1)=0\).  If
 967	  \(D-D'=\operatorname{div}(f)\), then
 968	  \(D'-D=\operatorname{div}(f^{-1})\), proving symmetry.  Adding the
 969	  equations for \(D\sim D'\) and \(D'\sim D''\), and using
 970	  \(\operatorname{div}(fg)=\operatorname{div}(f)+\operatorname{div}(g)\),
 971	  proves transitivity.
 972	\end{proof}
 973	
 974	\begin{definition}[Divisor class group]
 975	  \label{def:divisor_class_group}
 976	  \source{hartshorne-algebraic-geometry:page-0148}
 977	  \uses{thm:principal_hom}
 978	  The divisor class group is
 979	  \[
 980	    \operatorname{Cl}(X)
 981	      =\operatorname{Div}(X)/
 982	        \operatorname{im}\bigl(K(X)^\times
 983	          \xrightarrow{\operatorname{div}}\operatorname{Div}(X)\bigr).
 984	  \]
 985	\end{definition}
 986	
 987	\begin{theorem}[Degree on the divisor class group of a curve]
 988	  \label{thm:divisor_class_group_degree}
 989	  \source{hartshorne-algebraic-geometry:page-0155}
 990	  \uses{def:divisor_class_group, def:divisor_degree}
 991	  On a complete nonsingular curve over an algebraically closed field,
 992	  coefficient degree descends to a homomorphism
 993	  \[
 994	    \deg\colon\operatorname{Cl}(C)\longrightarrow\mathbb Z.
 995	  \]
 996	\end{theorem}
 997	\begin{proof}
 998	  \uses{thm:principal_deg_zero}
 999	  By \cref{thm:principal_deg_zero}, the degree homomorphism vanishes on the
1000	  subgroup of principal divisors, hence factors uniquely through the
1001	  quotient.
1002	\end{proof}
